using System;
using System.Collections.Generic;
using UnityEngine;

namespace LabSorting.Sorting
{
    // Maps an item's full-detail mesh to a cheaper mesh that shares its UVs and normals.
    // Generated by Editor/ItemMeshLodBuilder; read by ItemBatchRenderer for distant instances.
    public sealed class ItemMeshLodMap : ScriptableObject
    {
        [Serializable] public struct Entry { public Mesh full; public Mesh far; }
        public Entry[] entries = Array.Empty<Entry>();

        public Dictionary<Mesh, Mesh> Build()
        {
            var map = new Dictionary<Mesh, Mesh>(entries.Length);
            foreach (var entry in entries)
            {
                if (entry.full && entry.far && !map.ContainsKey(entry.full)) map.Add(entry.full, entry.far);
            }
            return map;
        }
    }
}
